package com.example.fulfillmentservice.controller;
import com.example.fulfillmentservice.model.*;import com.example.fulfillmentservice.service.FulfillmentService;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/fulfillments") @Tag(name="Fulfillment")
public class FulfillmentController{private final FulfillmentService service;public FulfillmentController(FulfillmentService service){this.service=service;}@PostMapping @Operation(summary="Create or return the fulfillment for an order")public ResponseEntity<Fulfillment>create(@Valid @RequestBody CreateFulfillmentRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(request));}@PostMapping("/{id}/approve") @Operation(summary="Approve the current step",description="Advances RECEIVED to PREPARING, PREPARING to DISPATCHED, or DISPATCHED to DELIVERED.")public Fulfillment approve(@PathVariable String id,@Valid @RequestBody(required=false) StepDecisionRequest request){return service.approve(id,request==null?null:request.reason());}@PostMapping("/{id}/reject") @Operation(summary="Reject the fulfillment",description="Moves an undelivered fulfillment to FAILED. A reason is required.")public Fulfillment reject(@PathVariable String id,@Valid @RequestBody StepDecisionRequest request){return service.reject(id,request.reason());}@GetMapping @Operation(summary="List fulfillments or find one by order")public Object list(@RequestParam(required=false)String orderId){return orderId==null?service.list():service.byOrder(orderId);}}
